<?php
require __DIR__.'/_init.php';require __DIR__.'/_layout.php';
function product_upload(array $file): string {
 if(($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK) throw new RuntimeException('Selecione uma imagem válida.');
 if(($file['size']??0)>8*1024*1024) throw new RuntimeException('A imagem deve ter até 8 MB.');
 $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;
 if(!$ext||!getimagesize($file['tmp_name'])) throw new RuntimeException('Use uma imagem JPG, PNG ou WEBP.');
 $dir=dirname(__DIR__).'/uploads/';if(!is_dir($dir)||!is_writable($dir))throw new RuntimeException('A pasta uploads precisa permitir gravação.');
 $name='produto-'.bin2hex(random_bytes(12)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],$dir.$name))throw new RuntimeException('Não foi possível salvar a imagem.');return 'uploads/'.$name;
}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';
 try{
  if($action==='save'){
   $id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');$sku=trim($_POST['sku']??'');$desc=trim($_POST['description']??'');$cat=(int)($_POST['category_id']??0)?:null;
   $price=(float)str_replace(',','.',$_POST['price']??'0');$promo=trim($_POST['promotional_price']??'');$promo=$promo===''?null:(float)str_replace(',','.',$promo);$stock=max(0,(int)($_POST['stock']??0));$featured=isset($_POST['featured'])?1:0;$active=isset($_POST['active'])?1:0;
   if($name===''||mb_strlen($name)>180)throw new RuntimeException('Informe o nome do produto.');if($price<0||($promo!==null&&($promo<0||$promo>$price)))throw new RuntimeException('Confira os preços. O promocional não pode superar o preço normal.');
   $image=null;if(!empty($_FILES['image']['name']))$image=product_upload($_FILES['image']);
   if($id){$old=db()->prepare('SELECT image_path FROM products WHERE id=?');$old->execute([$id]);$oldPath=$old->fetchColumn();if($image){$q=db()->prepare('UPDATE products SET category_id=?,sku=?,name=?,description=?,price=?,promotional_price=?,stock=?,image_path=?,featured=?,active=? WHERE id=?');$q->execute([$cat,$sku?:null,$name,$desc?:null,$price,$promo,$stock,$image,$featured,$active,$id]);if($oldPath)delete_local_file($oldPath);}else{$q=db()->prepare('UPDATE products SET category_id=?,sku=?,name=?,description=?,price=?,promotional_price=?,stock=?,featured=?,active=? WHERE id=?');$q->execute([$cat,$sku?:null,$name,$desc?:null,$price,$promo,$stock,$featured,$active,$id]);}}
   else{$q=db()->prepare('INSERT INTO products(category_id,sku,name,description,price,promotional_price,stock,image_path,featured,active) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$cat,$sku?:null,$name,$desc?:null,$price,$promo,$stock,$image,$featured,$active]);}
   flash('Produto salvo com sucesso.');
  }elseif($action==='delete'){$id=(int)$_POST['id'];$q=db()->prepare('SELECT image_path FROM products WHERE id=?');$q->execute([$id]);$img=$q->fetchColumn();db()->prepare('DELETE FROM products WHERE id=?')->execute([$id]);if($img)delete_local_file($img);flash('Produto removido. Os pedidos antigos preservam a descrição dos itens.');}
 }catch(Throwable $e){flash($e instanceof PDOException?'Não foi possível salvar. Verifique se o SKU já está cadastrado.':$e->getMessage(),'error');}
 header('Location: products.php');exit;
}
$edit=null;if(isset($_GET['edit'])){$q=db()->prepare('SELECT * FROM products WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$categories=db()->query('SELECT id,name FROM categories ORDER BY name')->fetchAll();$rows=db()->query('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC')->fetchAll();
admin_header('Produtos','products');?>
<div class="panel"><h2><?=$edit?'Editar produto':'Cadastrar produto'?></h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><div class="form-grid">
<label>Nome do produto<input name="name" maxlength="180" required value="<?=e($edit['name']??'')?>" placeholder="Ex.: Caneca personalizada"></label><label>Código / SKU<input name="sku" maxlength="60" value="<?=e($edit['sku']??'')?>" placeholder="Ex.: CAN-001"></label>
<label>Categoria<select name="category_id"><option value="">Sem categoria</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=((int)($edit['category_id']??0)===(int)$c['id'])?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label>
<label>Preço (R$)<input type="number" name="price" min="0" step="0.01" required value="<?=e((string)($edit['price']??'0.00'))?>"></label><label>Preço promocional (opcional)<input type="number" name="promotional_price" min="0" step="0.01" value="<?=e((string)($edit['promotional_price']??''))?>"></label><label>Estoque / disponibilidade<input type="number" name="stock" min="0" step="1" value="<?=e((string)($edit['stock']??0))?>"></label>
<label class="wide">Descrição<textarea name="description" rows="3"><?=e($edit['description']??'')?></textarea></label><label class="wide">Foto principal (JPG, PNG ou WEBP; até 8 MB)<input type="file" name="image" accept="image/jpeg,image/png,image/webp"><?php if(!empty($edit['image_path'])):?><img class="product-admin-thumb" src="../<?=e($edit['image_path'])?>" alt="Foto atual"><?php endif;?></label>
<label class="check-label"><input type="checkbox" name="featured" value="1" <?=!empty($edit['featured'])?'checked':''?>> Destacar na vitrine</label><label class="check-label"><input type="checkbox" name="active" value="1" <?=!isset($edit['active'])||!empty($edit['active'])?'checked':''?>> Produto ativo</label></div><div class="actions"><button class="btn primary">Salvar produto</button><?php if($edit):?><a class="btn outline" href="products.php">Cancelar</a><?php endif;?></div></form></div>
<div class="panel"><div class="panel-heading"><h2>Produtos cadastrados</h2><span class="muted"><?=count($rows)?> produto(s)</span></div><div class="table-wrap"><table><thead><tr><th>Produto</th><th>Categoria</th><th>Preço</th><th>Estoque</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="product-table-name"><?php if($r['image_path']):?><img src="../<?=e($r['image_path'])?>" alt=""><?php endif;?><span><strong><?=e($r['name'])?></strong><small><?=e($r['sku']??'')?></small></span></div></td><td><?=e($r['category_name']??'—')?></td><td>R$ <?=number_format((float)($r['promotional_price']??$r['price']),2,',','.')?></td><td><?=$r['stock']?></td><td><?=$r['active']?'Ativo':'Inativo'?></td><td><a class="btn soft" href="?edit=<?=$r['id']?>">Editar</a> <form class="inline-form" method="post" onsubmit="return confirm('Remover este produto?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger">Excluir</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6">Nenhum produto cadastrado. Use o formulário acima para começar.</td></tr><?php endif;?></tbody></table></div></div><?php admin_footer();
